// actor-runtime.ts: scheduler step example
async function runStep(actorState, tool) {
  // deterministic ordering: fetch -> enrich -> synthesize
  const fetchResult = await actorState.tools.fetch(tool.fetchArgs);
  const enriched = await actorState.tools.enrich(fetchResult);
  return actorState.tools.synthesize(enriched);
}
